{
  "name": "BioShake 微孔板加热振荡器",
  "name_en": "BioShake Heater-Shaker",
  "manufacturer": "QInstruments",
  "description": "台式微孔板加热振荡装置，用于对PCR板、微孔板等样品进行可控温度下的混匀。支持设定振荡转速、加速度/减速度，具备板夹锁定功能以稳定夹持样品板，并可进行温度设定与保持（部分型号支持主动冷却）。适用于分子生物学、酶标反应和样品预处理等实验流程及实验室自动化集成。",
  "description_en": "A benchtop microplate heater-shaker for mixing samples in PCR plates and microplates under controlled temperature. It supports setting shaking speed with acceleration/deceleration, features a plate-locking clamp for secure holding, and provides temperature setpoint control (with active cooling on some models). Ideal for molecular biology, assay incubation, and sample preparation, including lab automation workflows.",
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化设备，执行复位并回零，使其进入可运行状态。",
      "description_en": "Initialize the device by resetting and homing to prepare for operation."
    },
    {
      "action_name": "auto-stop",
      "description": "立即停止设备当前运行。",
      "description_en": "Immediately stop the device’s current operation."
    },
    {
      "action_name": "auto-reset",
      "description": "重置设备，清空通信缓冲并恢复到可用状态。",
      "description_en": "Reset the device, clearing communication buffers and restoring operability."
    },
    {
      "action_name": "auto-home",
      "description": "回零并建立基准位置。",
      "description_en": "Home the device and establish the reference position."
    },
    {
      "action_name": "auto-shake",
      "description": "以指定转速启动振荡，并设置加速度。",
      "description_en": "Start shaking at the specified speed and set acceleration."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "以指定减速度停止振荡。",
      "description_en": "Stop shaking using the specified deceleration."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定/夹紧微孔板以稳定固定。",
      "description_en": "Lock/clamp the microplate for secure holding."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁/释放微孔板夹持。",
      "description_en": "Unlock/release the microplate clamp."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度并启动温度控制。",
      "description_en": "Set the target temperature and start temperature control."
    },
    {
      "action_name": "auto-deactivate",
      "description": "停止温度控制。",
      "description_en": "Stop temperature control."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取设备是否支持板夹锁定功能。",
      "description_en": "Get whether the device supports plate locking."
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取设备是否支持主动冷却功能。",
      "description_en": "Get whether the device supports active cooling."
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    }
  ],
  "tag_hints": [
    "microplate heater shaker",
    "temperature control",
    "orbital shaking",
    "plate locking clamp",
    "active cooling",
    "PCR plate mixing",
    "lab automation",
    "speed and acceleration control"
  ]
}
